records.original_sql:
SELECT n, t FROM example.echo((
  SELECT n, t FROM (VALUES (1::BIGINT, 'x'),
                           (2::BIGINT, NULL),
                           (3::BIGINT, 'y'),
                           (4::BIGINT, NULL)) v(n, t)
)) WHERE n > 1 AND t IS NOT NULL ORDER BY n;

SELECT n, t FROM example.echo((
  SELECT n, t FROM (VALUES (1::BIGINT, 'a'),
                           (2::BIGINT, NULL),
                           (3::BIGINT, 'c')) v(n, t)
)) WHERE n = 2 OR t = 'c' ORDER BY n;

SELECT n, m FROM example.echo((
  SELECT n, m FROM (VALUES (1::BIGINT, 100::BIGINT),
                           (2::BIGINT, 200::BIGINT),
                           (2::BIGINT, 300::BIGINT),
                           (3::BIGINT, 400::BIGINT)) v(n, m)
)) WHERE n = 2 AND m >= 250 ORDER BY n, m;
